const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kyiv = ee.Geometry.Point(30.5234, 50.4501);
  const buffer_geom = kyiv.buffer(5000); // 5km buffer around Kyiv center

  const dateJan2022_start = '2022-01-01';
  const dateJan2022_end = '2022-01-31';
  const dateMar2022_start = '2022-03-01';
  const dateMar2022_end = '2022-03-31';

  const bandName = 'avg_rad'; // Average Radiance

  // 2. Data Acquisition
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  const jan2022_col = viirs.filterDate(dateJan2022_start, dateJan2022_end)
                           .filterBounds(buffer_geom);
  const mar2022_col = viirs.filterDate(dateMar2022_start, dateMar2022_end)
                           .filterBounds(buffer_geom);

  const jan2022_size = await jan2022_col.size().getInfo();
  const mar2022_size = await mar2022_col.size().getInfo();

  console.log(`Jan 2022 Images: ${jan2022_size}`);
  console.log(`Mar 2022 Images: ${mar2022_size}`);

  if (jan2022_size === 0 || mar2022_size === 0) {
    console.log("C1: Empty Collection (No images found for one or both periods).");
    return;
  }

  // Get the single monthly composite image for each period
  const jan2022_img = jan2022_col.first();
  const mar2022_img = mar2022_col.first();

  // 3. Processing and Calculation
  const scale = 1000; // Use a reasonable scale for regional mean

  // Reduce region for January 2022
  const jan2022_stats = await jan2022_img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer_geom,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const jan2022_mean = jan2022_stats ? jan2022_stats[bandName] : null;
  const jan2022_pixels = jan2022_stats ? jan2022_stats[bandName + '_count'] : 0;

  // Reduce region for March 2022
  const mar2022_stats = await mar2022_img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer_geom,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const mar2022_mean = mar2022_stats ? mar2022_stats[bandName] : null;
  const mar2022_pixels = mar2022_stats ? mar2022_stats[bandName + '_count'] : 0;

  console.log(`Jan 2022 Mean Radiance: ${jan2022_mean !== null ? jan2022_mean.toFixed(2) : 'N/A'}, Pixels: ${jan2022_pixels}`);
  console.log(`Mar 2022 Mean Radiance: ${mar2022_mean !== null ? mar2022_mean.toFixed(2) : 'N/A'}, Pixels: ${mar2022_pixels}`);

  // 4. Validation & Final Answer
  if (jan2022_pixels === 0 || mar2022_pixels === 0) {
    console.log("C2: No Valid Pixels (after processing, 0 pixels remain in the specified geometry).");
    return;
  }

  if (jan2022_mean === null || isNaN(jan2022_mean) || mar2022_mean === null || isNaN(mar2022_mean)) {
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  if (mar2022_mean < jan2022_mean) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
